import * as T from './vendor/three.js';
export function createCharacter(color='#2caee5',height=1.9){const root=new T.Group(),rig=new T.Group();root.add(rig);const blue=new T.MeshStandardMaterial({color,roughness:.65,flatShading:true}),white=new T.MeshStandardMaterial({color:'#c6eef3',roughness:.7,flatShading:true}),dark=new T.MeshStandardMaterial({color:'#154360'}),eye=new T.MeshStandardMaterial({color:'#f9eca0'});function part(geo,mat,parent,x,y,z){const m=new T.Mesh(geo,mat);m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}part(new T.CylinderGeometry(.23,.17,.58,5),white,rig,0,1.18,0);part(new T.BoxGeometry(.35,.22,.24),blue,rig,0,.84,0);part(new T.CylinderGeometry(.09,.09,.16,6),blue,rig,0,1.55,0);part(new T.IcosahedronGeometry(.27,1),white,rig,0,1.78,0);part(new T.BoxGeometry(.37,.26,.13),blue,rig,0,1.76,-.18);for(const x of[-.1,.1]){part(new T.SphereGeometry(.052,8,6),eye,rig,x,1.79,-.25);part(new T.SphereGeometry(.022,8,6),dark,rig,x,1.79,-.29)}const arms=[],legs=[];for(const s of[-1,1]){const arm=new T.Group();arm.position.set(s*.29,1.42,0);rig.add(arm);part(new T.CylinderGeometry(.075,.065,.34,5),blue,arm,0,-.17,0);const elbow=new T.Group();elbow.position.y=-.34;arm.add(elbow);part(new T.CylinderGeometry(.065,.045,.3,5),white,elbow,0,-.15,0);part(new T.IcosahedronGeometry(.07,0),blue,elbow,0,-.33,0);arms.push({arm,elbow});const leg=new T.Group();leg.position.set(s*.115,.8,0);rig.add(leg);part(new T.CylinderGeometry(.095,.065,.36,5),white,leg,0,-.18,0);const knee=new T.Group();knee.position.y=-.36;leg.add(knee);part(new T.CylinderGeometry(.065,.045,.35,5),blue,knee,0,-.175,0);part(new T.BoxGeometry(.14,.1,.27),blue,knee,0,-.36,-.055);legs.push({leg,knee})}rig.scale.setScalar(height/2.05);rig.position.y=-height/2;function animate(state,time){rig.scale.setScalar(height/2.05);rig.position.y=-height/2;rig.rotation.set(0,0,0);for(const {arm,elbow}of arms){arm.rotation.set(0,0,0);elbow.rotation.set(-.12,0,0)}for(const{leg,knee}of legs){leg.rotation.set(0,0,0);knee.rotation.set(0,0,0)}if(state==='run'||state==='walk'){const a=Math.sin(time*(state==='run'?13:7))*(state==='run'?.8:.4);legs[0].leg.rotation.x=a;legs[1].leg.rotation.x=-a;arms[0].arm.rotation.x=-a;arms[1].arm.rotation.x=a;for(const{knee}of legs)knee.rotation.x=.18;rig.position.y+=Math.abs(Math.cos(time*13))*.035}else if(state==='jump'){for(const{arm}of arms)arm.rotation.x=-1;legs[0].leg.rotation.x=-.55;legs[1].knee.rotation.x=.7}else if(state==='slide'){rig.scale.y*=.45;rig.rotation.x=-.15;rig.position.y=-.4;for(const{leg,knee}of legs){leg.rotation.x=-1;knee.rotation.x=1.5}}else if(state==='wave'){arms[1].arm.rotation.z=-2.5;arms[1].elbow.rotation.x=Math.sin(time*7)*.5}else if(state==='clap'){for(let i=0;i<2;i++){arms[i].arm.rotation.x=-1.1;arms[i].arm.rotation.z=(i===0?-1:1)*(.4+Math.sin(time*7)*.16);arms[i].elbow.rotation.x=-.8}}else rig.position.y+=Math.sin(time*2)*.012}root.userData.animate=animate;return root}
